		.rst_n(rst_n),
		.m_cyc(slot_sel[SLOT_SMOKE] & g_cyc),
		.m_stb(slot_sel[SLOT_SMOKE] & g_stb),
		.m_we(g_we),
		.m_adr(slot_sel[SLOT_SMOKE] ? g_adr_dec & ~32'hffffffc0 : 32'd0),
		.m_dat(g_wdata),
		.m_sel(g_sel),
		.m_tga(g_tga_bank),
		.m_ack(smoke_pipe_ack),
		.m_rdat(smoke_pipe_rdat),
		.s_cyc(smoke_i_wb_cyc),
		.s_stb(smoke_i_wb_stb),
		.s_we(smoke_i_wb_we),
		.s_adr(smoke_i_wb_adr),
		.s_dat(smoke_i_wb_dat),
		.s_sel(smoke_i_wb_sel),
		.s_tga(smoke_i_wb_tga_bank),
		.s_ack(smoke_o_wb_ack),
		.s_rdat(smoke_o_wb_dat)
	);

	logic [31:0] rsp_dat;
	logic        rsp_ack;

	assign rsp_dat = ({32{slot_sel[SLOT_SRAM]}} & sram_pipe_rdat)
	               | ({32{slot_sel[SLOT_FLASH_XIP]}} & flash_xip_pipe_rdat)
	               | ({32{slot_sel[SLOT_FLASH_CFG]}} & flash_cfg_o_wb_dat)
	               | ({32{slot_sel[SLOT_UART]}} & uart_pipe_rdat)
	               | ({32{slot_sel[SLOT_TESTOUT]}} & testout_pipe_rdat)
	               | ({32{slot_sel[SLOT_CH0]}} & ch0_pipe_rdat)
	               | ({32{slot_sel[SLOT_CH1]}} & ch1_pipe_rdat)
	               | ({32{slot_sel[SLOT_SMOKE]}} & smoke_pipe_rdat);
	assign rsp_ack = (unmapped & g_stb)
	               | (sram_pipe_ack)
	               | (flash_xip_pipe_ack)
	               | (slot_sel[SLOT_FLASH_CFG] & flash_cfg_o_wb_ack)
	               | (uart_pipe_ack)
	               | (testout_pipe_ack)
	               | (ch0_pipe_ack)
	               | (ch1_pipe_ack)
	               | (smoke_pipe_ack);

	//------------------------------------------------------------------------------
	//  Master response: only the granted slot sees DAT/ACK
	//------------------------------------------------------------------------------
	assign cpu_i_wb_dat = {32{gsel[0]}} & rsp_dat;
	assign cpu_i_wb_ack = gsel[0] & rsp_ack;
	assign m1_rdat_q = {32{gsel[1]}} & rsp_dat;
	assign m1_ack_q  = gsel[1] & rsp_ack;
	assign dbg_i_wb_dat = m1_prdat;
	assign dbg_i_wb_ack = m1_pack;

endmodule
